// داده لوگوهای خودرو
// این فایل می‌تواند با لوگوهای استخراج شده از فایل DXF پر شود
// یا لوگوها را می‌توان به صورت تصویر در پوشه public/logos قرار داد

export interface CarLogo {
  id: string;
  name: string;
  image: string; // مسیر تصویر یا base64
  category?: string;
}

// لیست لوگوهای خودرو
// می‌توانید لوگوها را از فایل DXF استخراج کرده و به این لیست اضافه کنید
// یا تصاویر را در پوشه public/logos قرار داده و مسیر آن‌ها را اینجا اضافه کنید
