"use client";

import { useState, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { X, Upload, Image as ImageIcon, Loader2, Search, Grid3x3 } from "lucide-react";
import { SafeImage } from "@/components/ui/safe-image";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";
import { carLogos, logoCategories, type CarLogo } from "@/data/car-logos";
import { ScrollArea } from "@/components/ui/scroll-area";

interface LogoSelectorProps {
  image: string | null;
  onChange: (image: string | null) => void;
  className?: string;
  label?: string;
}

export function LogoSelector({
  image,
  onChange,
  className,
  label = "لوگو خودرو",
}: LogoSelectorProps) {
  const [uploading, setUploading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("همه");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith("image/")) {
      toast({
        title: "خطا",
        description: "فقط فایل‌های تصویری مجاز هستند",
        variant: "destructive",
      });
      return;
    }

    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      toast({
        title: "خطا",
        description: "حجم فایل نباید بیشتر از 5 مگابایت باشد",
        variant: "destructive",
      });
      return;
    }

    setUploading(true);

    try {
      // Convert to base64
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        onChange(base64String);
        setUploading(false);
        toast({
          title: "موفق",
          description: "تصویر با موفقیت آپلود شد",
        });
      };
      reader.onerror = () => {
        setUploading(false);
        toast({
          title: "خطا",
          description: "خطا در خواندن فایل",
          variant: "destructive",
        });
      };
      reader.readAsDataURL(file);
    } catch (error) {
      setUploading(false);
      toast({
        title: "خطا",
        description: "خطا در آپلود تصویر",
        variant: "destructive",
      });
    }
  };

  const handleRemove = () => {
    onChange(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleLogoSelect = (logo: CarLogo) => {
    onChange(logo.image);
    toast({
      title: "موفق",
      description: `لوگو ${logo.name} انتخاب شد`,
    });
  };

  // Filter logos based on search and category
  const filteredLogos = carLogos.filter((logo) => {
    const matchesSearch =
      logo.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      logo.id.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory =
      selectedCategory === "همه" || logo.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className={cn("space-y-4", className)}>
      <label className="text-sm font-medium">{label}</label>
      
      <Tabs defaultValue="gallery" className="w-full">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="gallery" className="flex items-center gap-2">
            <Grid3x3 className="h-4 w-4" />
            انتخاب از گالری
          </TabsTrigger>
          <TabsTrigger value="upload" className="flex items-center gap-2">
            <Upload className="h-4 w-4" />
            آپلود تصویر
          </TabsTrigger>
        </TabsList>

        {/* Gallery Tab */}
        <TabsContent value="gallery" className="space-y-4 mt-4">
          {carLogos.length > 0 ? (
            <>
              {/* Search and Filter */}
              <div className="space-y-3">
                <div className="relative">
                  <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder="جستجوی لوگو..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pr-9"
                  />
                </div>
                
                {/* Category Filter */}
                <ScrollArea className="w-full">
                  <div className="flex gap-2 pb-2">
                    {logoCategories.map((category) => (
                      <Button
                        key={category}
                        type="button"
                        variant={selectedCategory === category ? "default" : "outline"}
                        size="sm"
                        onClick={() => setSelectedCategory(category)}
                        className="text-xs whitespace-nowrap"
                      >
                        {category}
                      </Button>
                    ))}
                  </div>
                </ScrollArea>
              </div>

              {/* Logo Grid */}
              {filteredLogos.length > 0 ? (
                <ScrollArea className="w-full h-[300px]">
                  <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 gap-3 p-1">
                    {filteredLogos.map((logo) => (
                      <button
                        key={logo.id}
                        type="button"
                        onClick={() => handleLogoSelect(logo)}
                        className={cn(
                          "relative group aspect-square rounded-lg border-2 overflow-hidden bg-muted hover:border-primary transition-all",
                          image === logo.image && "border-primary ring-2 ring-primary/20"
                        )}
                        title={logo.name}
                      >
                        <SafeImage
                          src={logo.image}
                          alt={logo.name}
                          className="w-full h-full object-contain p-2"
                          fallback={
                            <div className="w-full h-full flex items-center justify-center">
                              <ImageIcon className="h-6 w-6 text-muted-foreground" />
                            </div>
                          }
                        />
                        {image === logo.image && (
                          <div className="absolute inset-0 bg-primary/10 flex items-center justify-center">
                            <div className="h-6 w-6 rounded-full bg-primary flex items-center justify-center">
                              <div className="h-2 w-2 rounded-full bg-white" />
                            </div>
                          </div>
                        )}
                      </button>
                    ))}
                  </div>
                </ScrollArea>
              ) : (
                <div className="flex flex-col items-center justify-center py-12 text-center border border-dashed border-border rounded-lg bg-muted/20">
                  <ImageIcon className="h-12 w-12 text-muted-foreground mb-4" />
                  <p className="text-sm font-medium mb-1">لوگویی یافت نشد</p>
                  <p className="text-xs text-muted-foreground">
                    {searchQuery
                      ? "لطفاً عبارت جستجو را تغییر دهید"
                      : "هنوز لوگویی به گالری اضافه نشده است"}
                  </p>
                </div>
              )}
            </>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 text-center border border-dashed border-border rounded-lg bg-muted/20">
              <Grid3x3 className="h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-sm font-medium mb-1">گالری لوگو خالی است</p>
              <p className="text-xs text-muted-foreground">
                می‌توانید لوگوها را از فایل DXF استخراج کرده و به گالری اضافه کنید
              </p>
            </div>
          )}
        </TabsContent>

        {/* Upload Tab */}
        <TabsContent value="upload" className="space-y-4 mt-4">
          <div className="flex items-start gap-4">
            {image ? (
              <div className="relative group">
                <div className="w-24 h-24 rounded-lg border-2 border-border overflow-hidden bg-muted flex items-center justify-center">
                  <SafeImage
                    src={image}
                    alt={label}
                    className="w-full h-full object-contain"
                    fallback={
                      <ImageIcon className="h-8 w-8 text-muted-foreground" />
                    }
                  />
                </div>
                <Button
                  type="button"
                  variant="destructive"
                  size="icon"
                  className="absolute -top-2 -right-2 h-6 w-6 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={handleRemove}
                >
                  <X className="h-3 w-3" />
                </Button>
              </div>
            ) : (
              <div className="w-24 h-24 rounded-lg border-2 border-dashed border-border flex items-center justify-center bg-muted/30">
                <ImageIcon className="h-8 w-8 text-muted-foreground" />
              </div>
            )}
            <div className="flex-1 space-y-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => fileInputRef.current?.click()}
                disabled={uploading}
                className="w-full"
              >
                {uploading ? (
                  <>
                    <Loader2 className="ml-2 h-4 w-4 animate-spin" />
                    در حال آپلود...
                  </>
                ) : (
                  <>
                    <Upload className="ml-2 h-4 w-4" />
                    {image ? "تغییر لوگو" : "آپلود لوگو"}
                  </>
                )}
              </Button>
              <p className="text-xs text-muted-foreground">
                فرمت‌های مجاز: JPG, PNG, GIF (حداکثر 5MB)
              </p>
            </div>
          </div>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileSelect}
            className="hidden"
          />
        </TabsContent>
      </Tabs>

      {/* Preview */}
      {image && (
        <div className="pt-4 border-t border-border/30">
          <p className="text-xs text-muted-foreground mb-2">پیش‌نمایش:</p>
          <div className="w-16 h-16 rounded-lg border border-border overflow-hidden bg-muted flex items-center justify-center">
            <SafeImage
              src={image}
              alt="Preview"
              className="w-full h-full object-contain"
              fallback={
                <ImageIcon className="h-6 w-6 text-muted-foreground" />
              }
            />
          </div>
        </div>
      )}
    </div>
  );
}

